#!/usr/bin/env python3
"""Build the final Stage U-B V6 observable table from preserved summaries."""
from __future__ import annotations
import csv,json
from pathlib import Path

HERE=Path(__file__).resolve().parent; ROOT=HERE.parent
co=json.loads((HERE/'coo'/'bands'/'results.json').read_text(encoding='utf-8'))
mn=json.loads((HERE/'mno'/'scf_observables.json').read_text(encoding='utf-8'))
mb=json.loads((HERE/'mno'/'bands'/'results.json').read_text(encoding='utf-8'))
u=json.loads((HERE/'mno'/'authoritative_u_inputs.json').read_text(encoding='utf-8'))
ni_pbe=json.loads((ROOT/'results/stage-ub-v6-observables/run-records/nio-dft.json').read_text(encoding='utf-8'))
ni_lru=json.loads((ROOT/'results/stage-ub-v6-observables/run-records/nio-dft_lru.json').read_text(encoding='utf-8'))

def avg_abs(a:float,b:float)->float:return (abs(a)+abs(b))/2
def moments(run:dict,site0:str,site1:str)->tuple[float,float,float]:
    atoms=run['convergence']['mulliken_atoms']; vals={x['species']:x['moment_muB'] for x in atoms}
    return vals[site0],vals[site1],avg_abs(vals[site0],vals[site1])

ni0=ni_pbe['observables']['correlated_site_moments_muB']; ni1=ni_lru['observables']['correlated_site_moments_muB']
mn_runs=mn['runs']; mn_p0,mn_p1= (x['moment_muB'] for x in mn_runs['PBE']['convergence']['mulliken_atoms'][:2])
mn_l0,mn_l1,mn_lavg=moments(mn_runs['PBE+LR-U central'],'MnLR0','MnLR1')
mn_low0,mn_low1,mn_lowavg=moments(mn_runs['PBE+LR-U low'],'MnLR0','MnLR1')
mn_hi0,mn_hi1,mn_hiavg=moments(mn_runs['PBE+LR-U high'],'MnLR0','MnLR1')
co_p0=co['methods']['PBE']['scf_convergence']['mulliken_atoms'][0]['moment_muB']; co_p1=co['methods']['PBE']['scf_convergence']['mulliken_atoms'][1]['moment_muB']
co_l0=co['methods']['PBE+LR-U']['scf_convergence']['mulliken_atoms'][0]['moment_muB']; co_l1=co['methods']['PBE+LR-U']['scf_convergence']['mulliken_atoms'][1]['moment_muB']

