 {'material':'FeO','xc':'PBE','u_site0_eV':5.638281766243177,'u_site1_eV':5.638315883828983,'u_qualification':'ACCEPTED','pbe_state':'METAL','pbe_gap_mesh_eV':0.0,'pbe_local_moment_muB':3.64505,'lru_state':'INSULATOR','lru_gap_mesh_eV':2.30591557,'lru_gap_seekpath_eV':2.332998519,'lru_min_direct_gap_seekpath_eV':2.480536168,'lru_local_moment_muB':3.9089,'observable_status':'COMPLETE','u_low_site0_eV':None,'u_low_site1_eV':None,'u_high_site0_eV':None,'u_high_site1_eV':None,'u_low_site0_fraction':None,'u_low_site1_fraction':None,'u_high_site0_fraction':None,'u_high_site1_fraction':None,'gap_low_eV':None,'gap_central_eV':None,'gap_high_eV':None,'moment_low_muB':None,'moment_central_muB':None,'moment_high_muB':None,'u_sensitivity_observable_status':'NOT_RUN','pbe_local_moment_site0_muB':3.64505,'pbe_local_moment_site1_muB':-3.64505,'lru_local_moment_site0_muB':3.908901,'lru_local_moment_site1_muB':-3.908899,'pbe_route_state':'METAL','lru_route_state':'INSULATOR'},
 {'material':'CoO','xc':'PBE','u_site0_eV':5.817148502021659,'u_site1_eV':5.815019855497104,'u_qualification':'REVIEW','pbe_state':'METAL','pbe_gap_mesh_eV':0.0,'pbe_local_moment_muB':avg_abs(co_p0,co_p1),'lru_state':'INSULATOR','lru_gap_mesh_eV':2.71482278,'lru_gap_seekpath_eV':co['methods']['PBE+LR-U']['cbm']['indirect_gap_eV'],'lru_min_direct_gap_seekpath_eV':co['methods']['PBE+LR-U']['minimum_direct_gap']['gap_eV'],'lru_local_moment_muB':avg_abs(co_l0,co_l1),'observable_status':'COMPLETE','u_low_site0_eV':None,'u_low_site1_eV':None,'u_high_site0_eV':None,'u_high_site1_eV':None,'u_low_site0_fraction':None,'u_low_site1_fraction':None,'u_high_site0_fraction':None,'u_high_site1_fraction':None,'gap_low_eV':None,'gap_central_eV':None,'gap_high_eV':None,'moment_low_muB':None,'moment_central_muB':None,'moment_high_muB':None,'u_sensitivity_observable_status':'NOT_RUN','pbe_local_moment_site0_muB':co_p0,'pbe_local_moment_site1_muB':co_p1,'lru_local_moment_site0_muB':co_l0,'lru_local_moment_site1_muB':co_l1,'pbe_route_state':'METAL','lru_route_state':co['methods']['PBE+LR-U']['route_classification']},
